// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address actor, uint256 warpTo) public {
        vm.assume(actor != address(0));
        uint256 amount = 10 ether;

        uint256 targetTs = bound(warpTo, block.timestamp + 1, block.timestamp + 100000);

        vm.deal(actor, amount);

        vm.warp(targetTs);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok);

        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}
